simulators = {
  "1": {
    "title": "Ecosystem Biotic & Abiotic Balance Studio",
    "description": "Simulate interactions between climatic abiotic factors (temperature, rainfall) and living biotic communities (vegetation, herbivores, predators) to discover ecosystem equilibrium.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Annual Rainfall:</span>\n                        <input type=\"range\" id=\"sim1_rain_slider\" min=\"20\" max=\"200\" value=\"100\" step=\"10\" oninput=\"sim1Update()\" class=\"w-24 accent-emerald-500\">\n                        <span id=\"sim1_rain_txt\" class=\"text-emerald-400 font-mono font-bold\">100 cm</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Mean Temp:</span>\n                        <input type=\"range\" id=\"sim1_temp_slider\" min=\"5\" max=\"45\" value=\"25\" step=\"1\" oninput=\"sim1Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim1_temp_txt\" class=\"text-amber-400 font-mono font-bold\">25°C</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim1Reset()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Reset Habitat</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim1_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Biome Classification</div>\n                        <div id=\"sim1_val_biome\" class=\"text-emerald-400 font-bold text-sm\">Temperate Forest</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Producer Canopy Biomass</div>\n                        <div id=\"sim1_val_biomass\" class=\"text-teal-400 font-bold text-sm\">7,800 kg/ha</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Herbivore Grazing Density</div>\n                        <div id=\"sim1_val_herbivores\" class=\"text-cyan-400 font-bold text-sm\">45 deer/km²</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Equilibrium Index</div>\n                        <div id=\"sim1_val_stability\" class=\"text-amber-400 font-bold text-sm\">Balanced (92%)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "2": {
    "title": "Artificial Aquarium Life-Support Studio",
    "description": "Experiment with Activity 13.1 by adjusting aerator oxygenation, fish stocking density, and aquatic plants to observe oxygen levels and toxic waste accumulation in an artificial ecosystem.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim2_btn_aerator\" onclick=\"sim2ToggleAerator()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold\">Aerator: ON 🫧</button>\n                        <button onclick=\"sim2FeedFish()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Feed Fish 🪱</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Fish Count:</span>\n                        <input type=\"range\" id=\"sim2_fish_slider\" min=\"2\" max=\"15\" value=\"6\" step=\"1\" oninput=\"sim2Update()\" class=\"w-24 accent-cyan-500\">\n                        <span id=\"sim2_fish_txt\" class=\"text-cyan-400 font-mono font-bold\">6 Fish</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim2CleanTank()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Clean Tank 🧼</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim2_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Dissolved O₂ Saturation</div>\n                        <div id=\"sim2_val_o2\" class=\"text-emerald-400 font-bold text-sm\">8.2 mg/L (Optimal)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Toxic Ammonia / Waste</div>\n                        <div id=\"sim2_val_waste\" class=\"text-amber-400 font-bold text-sm\">0.15 ppm (Safe)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Aquatic Plants (Hydrilla)</div>\n                        <div id=\"sim2_val_plants\" class=\"text-teal-400 font-bold text-sm\">Photosynthesizing</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ecosystem Status</div>\n                        <div id=\"sim2_val_status\" class=\"text-cyan-400 font-bold text-sm\">Healthy Aquarium</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "3": {
    "title": "Ecological Trophic Roles Lab",
    "description": "Examine how producers, primary consumers, secondary consumers, and specialized parasites acquire nourishment and drive metabolic energy flow.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Select Organism:</span>\n                        <select id=\"sim3_sel_organism\" onchange=\"sim3Update()\" class=\"bg-slate-800 text-emerald-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"producer\">Green Plant (Autotroph)</option>\n                            <option value=\"herbivore\">Grasshopper (Primary Consumer)</option>\n                            <option value=\"carnivore\">Frog (Secondary Consumer)</option>\n                            <option value=\"parasite\">Cuscuta / Amarbel (Plant Parasite)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Sunlight Level:</span>\n                        <input type=\"range\" id=\"sim3_sun_slider\" min=\"10\" max=\"100\" value=\"80\" step=\"5\" oninput=\"sim3Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim3_sun_txt\" class=\"text-amber-400 font-mono font-bold\">80%</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim3_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Nutritional Category</div>\n                        <div id=\"sim3_val_mode\" class=\"text-emerald-400 font-bold text-sm\">Photoautotrophic</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Primary Energy Source</div>\n                        <div id=\"sim3_val_source\" class=\"text-teal-400 font-bold text-sm\">Solar Photons + CO₂</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Chlorophyll Presence</div>\n                        <div id=\"sim3_val_chloro\" class=\"text-cyan-400 font-bold text-sm\">Active Chloroplasts</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Trophic Rank</div>\n                        <div id=\"sim3_val_rank\" class=\"text-amber-400 font-bold text-sm\">Trophic Level 1</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "4": {
    "title": "Decomposer Microbial Mineralization Engine",
    "description": "Observe saprophytic bacteria and fungi breaking down dead organic detritus, releasing essential nitrogen, phosphorus, and potassium ions to replenish soil fertility.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Dead Detritus Input:</span>\n                        <input type=\"range\" id=\"sim4_waste_slider\" min=\"10\" max=\"100\" value=\"50\" step=\"5\" oninput=\"sim4Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim4_waste_txt\" class=\"text-amber-400 font-mono font-bold\">50 kg</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Microbial Density:</span>\n                        <input type=\"range\" id=\"sim4_micro_slider\" min=\"1\" max=\"5\" value=\"3\" step=\"1\" oninput=\"sim4Update()\" class=\"w-24 accent-emerald-500\">\n                        <span id=\"sim4_micro_txt\" class=\"text-emerald-400 font-mono font-bold\">Moderate (3×)</span>\n                    </div>\n                    <button onclick=\"sim4ToggleEnzymes()\" id=\"sim4_btn_enz\" class=\"px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold\">Enzymes: ON</button>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim4_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Mineralization Rate</div>\n                        <div id=\"sim4_val_rate\" class=\"text-emerald-400 font-bold text-sm\">4.8 kg/day</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Released Soil Nutrients (NPK)</div>\n                        <div id=\"sim4_val_npk\" class=\"text-teal-400 font-bold text-sm\">340 mg/kg</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Humus Soil Organic Layer</div>\n                        <div id=\"sim4_val_humus\" class=\"text-cyan-400 font-bold text-sm\">Rich Humus (6.2%)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Soil Recycling Status</div>\n                        <div id=\"sim4_val_status\" class=\"text-amber-400 font-bold text-sm\">Actively Replenished</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "5": {
    "title": "4-Tier Food Chain Cascade Simulator",
    "description": "Construct linear terrestrial and aquatic food chains, and simulate trophic cascade disruptions when an intermediate consumer tier is removed.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Habitat Chain:</span>\n                        <select id=\"sim5_sel_chain\" onchange=\"sim5UpdateChain()\" class=\"bg-slate-800 text-emerald-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"grassland\">Grassland: Grass -> Insect -> Frog -> Snake -> Hawk</option>\n                            <option value=\"forest\">Forest: Tree -> Deer -> Tiger</option>\n                            <option value=\"pond\">Pond: Algae -> Zooplankton -> Small Fish -> Crane</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim5_btn_disrupt\" onclick=\"sim5ToggleDisruption()\" class=\"px-3 py-1 rounded-lg bg-rose-600 hover:bg-rose-500 text-white font-bold\">Remove Intermediate Tier ⚡</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim5_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Producer Level (T1)</div>\n                        <div id=\"sim5_val_t1\" class=\"text-emerald-400 font-bold text-sm\">Healthy Abundance</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Primary Consumer (T2)</div>\n                        <div id=\"sim5_val_t2\" class=\"text-teal-400 font-bold text-sm\">Regulated Herbivory</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Secondary Consumer (T3)</div>\n                        <div id=\"sim5_val_t3\" class=\"text-cyan-400 font-bold text-sm\">Active Predation</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apex Predator (T4/T5)</div>\n                        <div id=\"sim5_val_t4\" class=\"text-amber-400 font-bold text-sm\">Sustained Population</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "6": {
    "title": "Solar Energy 1% Photochemical Capture Studio",
    "description": "Quantify how terrestrial leaves intercept incident solar radiation, reflecting and dissipating 99% while capturing exactly 1% into synthesized carbohydrate chemical bond energy.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Incident Solar Energy:</span>\n                        <input type=\"range\" id=\"sim6_solar_slider\" min=\"100000\" max=\"2000000\" value=\"1000000\" step=\"100000\" oninput=\"sim6Update()\" class=\"w-32 accent-amber-500\">\n                        <span id=\"sim6_solar_txt\" class=\"text-amber-400 font-mono font-bold\">1,000,000 J</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Canopy Cover:</span>\n                        <input type=\"range\" id=\"sim6_canopy_slider\" min=\"50\" max=\"100\" value=\"100\" step=\"5\" oninput=\"sim6Update()\" class=\"w-24 accent-emerald-500\">\n                        <span id=\"sim6_canopy_txt\" class=\"text-emerald-400 font-mono font-bold\">100%</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim6_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Captured Plant Energy (1%)</div>\n                        <div id=\"sim6_val_captured\" class=\"text-emerald-400 font-bold text-sm\">10,000 J</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Reflected & Transmitted (99%)</div>\n                        <div id=\"sim6_val_lost\" class=\"text-rose-400 font-bold text-sm\">990,000 J</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Photosynthetic Efficiency</div>\n                        <div id=\"sim6_val_eff\" class=\"text-cyan-400 font-bold text-sm\">Exactly 1.0%</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Gross Primary Output</div>\n                        <div id=\"sim6_val_gpp\" class=\"text-amber-400 font-bold text-sm\">2.4 g Glucose/m²</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "7": {
    "title": "Lindeman 10% Trophic Energy Pyramid",
    "description": "Calculate and visualize step-by-step 90% metabolic energy dissipation and the remaining 10% trophic transfer across progressive ecological tiers.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Producer Energy (T1):</span>\n                        <input type=\"range\" id=\"sim7_energy_slider\" min=\"1000\" max=\"50000\" value=\"10000\" step=\"1000\" oninput=\"sim7Update()\" class=\"w-32 accent-emerald-500\">\n                        <span id=\"sim7_energy_txt\" class=\"text-emerald-400 font-mono font-bold\">10,000 J</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Trophic Levels:</span>\n                        <select id=\"sim7_sel_tiers\" onchange=\"sim7Update()\" class=\"bg-slate-800 text-amber-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"4\">4 Levels (Producers -> Apex)</option>\n                            <option value=\"5\">5 Levels (Extended Chain)</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim7_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Herbivore Energy (T2)</div>\n                        <div id=\"sim7_val_t2\" class=\"text-emerald-400 font-bold text-sm\">1,000 J (10%)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Small Carnivore Energy (T3)</div>\n                        <div id=\"sim7_val_t3\" class=\"text-teal-400 font-bold text-sm\">100 J (1%)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apex Predator Energy (T4)</div>\n                        <div id=\"sim7_val_t4\" class=\"text-cyan-400 font-bold text-sm\">10 J (0.1%)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Dissipated Heat</div>\n                        <div id=\"sim7_val_heat\" class=\"text-rose-400 font-bold text-sm\">9,990 J Lost</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "8": {
    "title": "Interconnected Food Web Dynamic Graph",
    "description": "Interact with a multi-branching network of feeding links to explore how dietary flexibility and alternative prey pathways buffer biological communities against sudden species collapse.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Trigger Environmental Shock:</span>\n                        <select id=\"sim8_sel_shock\" onchange=\"sim8ApplyShock()\" class=\"bg-slate-800 text-amber-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"none\">Normal Equilibrium</option>\n                            <option value=\"insect_blight\">Insect Crop Blight (-80% Insects)</option>\n                            <option value=\"rodent_decline\">Rodent Viral Outbreak (-80% Mice)</option>\n                            <option value=\"frog_decline\">Wetland Drainage (-80% Frogs)</option>\n                        </select>\n                    </div>\n                    <button onclick=\"sim8ResetWeb()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Reset Web</button>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim8_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Predator Dietary Shift</div>\n                        <div id=\"sim8_val_shift\" class=\"text-emerald-400 font-bold text-sm\">Balanced across prey</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Network Redundancy</div>\n                        <div id=\"sim8_val_redundancy\" class=\"text-teal-400 font-bold text-sm\">8 Interconnected Links</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Community Homeostasis</div>\n                        <div id=\"sim8_val_stability\" class=\"text-cyan-400 font-bold text-sm\">Highly Stable (95%)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Trophic Cascade Impact</div>\n                        <div id=\"sim8_val_cascade\" class=\"text-amber-400 font-bold text-sm\">Absorbed by Web</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "9": {
    "title": "Unidirectional Energy Flow vs Cyclic Nutrient Studio",
    "description": "Compare the strictly one-way dissipation of solar metabolic energy into degraded thermal heat with the perpetual cyclic biogeochemical recycling of mineral nutrients.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">View Mode:</span>\n                        <select id=\"sim9_sel_mode\" onchange=\"sim9Update()\" class=\"bg-slate-800 text-emerald-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"energy\">Energy Flow (One-Way Dissipation)</option>\n                            <option value=\"nutrients\">Mineral Nutrients (Closed Cyclic Recirculation)</option>\n                            <option value=\"both\">Integrated Comparison</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Solar Input:</span>\n                        <input type=\"range\" id=\"sim9_solar_slider\" min=\"50\" max=\"150\" value=\"100\" step=\"10\" oninput=\"sim9Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim9_solar_txt\" class=\"text-amber-400 font-mono font-bold\">100%</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim9_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Thermodynamic Pathway</div>\n                        <div id=\"sim9_val_flow\" class=\"text-emerald-400 font-bold text-sm\">Strictly One-Way</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Dissipated Heat Radiation</div>\n                        <div id=\"sim9_val_heat\" class=\"text-rose-400 font-bold text-sm\">Continuous Thermal Loss</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Nutrient Biogeochemical Cycle</div>\n                        <div id=\"sim9_val_nutrient\" class=\"text-cyan-400 font-bold text-sm\">100% Conserved via Soil</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">External Input Requirement</div>\n                        <div id=\"sim9_val_solar_dep\" class=\"text-amber-400 font-bold text-sm\">Uninterrupted Solar Influx</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "10": {
    "title": "Biological Toxic Magnification Ladder",
    "description": "Observe non-biodegradable synthetic chemicals (like DDT and mercury) multiplying across aquatic trophic tiers to reach lethal concentrations in apex human tissues.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Water Initial Toxin:</span>\n                        <input type=\"range\" id=\"sim10_toxin_slider\" min=\"1\" max=\"10\" value=\"2\" step=\"1\" oninput=\"sim10Update()\" class=\"w-28 accent-rose-500\">\n                        <span id=\"sim10_toxin_txt\" class=\"text-rose-400 font-mono font-bold\">0.02 ppb</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Chemical Agent:</span>\n                        <select id=\"sim10_sel_toxin\" onchange=\"sim10Update()\" class=\"bg-slate-800 text-amber-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"ddt\">DDT Organochlorine Pesticide</option>\n                            <option value=\"mercury\">Methylmercury Heavy Metal</option>\n                            <option value=\"lead\">Lead Industrial Residue</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim10_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Phytoplankton Level</div>\n                        <div id=\"sim10_val_plankton\" class=\"text-emerald-400 font-bold text-sm\">0.04 ppm (2,000×)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Small Fish Level</div>\n                        <div id=\"sim10_val_smallfish\" class=\"text-teal-400 font-bold text-sm\">0.5 ppm (25,000×)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Large Predatory Fish</div>\n                        <div id=\"sim10_val_bigfish\" class=\"text-amber-400 font-bold text-sm\">2.0 ppm (100,000×)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apex Consumer (Human)</div>\n                        <div id=\"sim10_val_apex\" class=\"text-rose-500 font-bold text-sm\">25.0 ppm (1,250,000×)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "11": {
    "title": "Pesticide Surface Wash vs Systemic Residue Lab",
    "description": "Experiment with Activity 13.3 by testing cold water, salt wash, and boiling on vegetables to discover why surface washing removes topical dust but leaves absorbed systemic pesticides intact.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Treatment:</span>\n                        <select id=\"sim11_sel_treatment\" onchange=\"sim11ApplyTreatment()\" class=\"bg-slate-800 text-emerald-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"raw\">Unwashed Harvest (100% Contaminated)</option>\n                            <option value=\"tap_water\">Running Tap Water Wash</option>\n                            <option value=\"salt_soak\">2% Salt Solution Soak (15 mins)</option>\n                            <option value=\"peeled\">Deep Skin Peeling</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim11Reset()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Reset Produce</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim11_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Surface Coating Toxin</div>\n                        <div id=\"sim11_val_surface\" class=\"text-rose-400 font-bold text-sm\">100% Present</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Internal Vascular Residue</div>\n                        <div id=\"sim11_val_systemic\" class=\"text-amber-400 font-bold text-sm\">100% Embedded</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Net Decontamination</div>\n                        <div id=\"sim11_val_decon\" class=\"text-cyan-400 font-bold text-sm\">0% Cleared</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Safe Consumption Status</div>\n                        <div id=\"sim11_val_safety\" class=\"text-rose-500 font-bold text-sm\">Hazardous Over-Limit</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "12": {
    "title": "Two-Step Photochemical Ozone Synthesis",
    "description": "Simulate stratospheric ozone synthesis: UV photons split diatomic oxygen into nascent oxygen atoms (O₂ -> O + O), which then collide with O₂ molecules to form protective triatomic ozone (O + O₂ -> O₃).",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Solar UV Intensity:</span>\n                        <input type=\"range\" id=\"sim12_uv_slider\" min=\"20\" max=\"100\" value=\"70\" step=\"5\" oninput=\"sim12Update()\" class=\"w-28 accent-cyan-500\">\n                        <span id=\"sim12_uv_txt\" class=\"text-cyan-400 font-mono font-bold\">70% UV</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Stratospheric Altitude:</span>\n                        <input type=\"range\" id=\"sim12_alt_slider\" min=\"15\" max=\"40\" value=\"25\" step=\"1\" oninput=\"sim12Update()\" class=\"w-24 accent-indigo-500\">\n                        <span id=\"sim12_alt_txt\" class=\"text-indigo-400 font-mono font-bold\">25 km</span>\n                    </div>\n                    <button onclick=\"sim12TriggerPhoton()\" class=\"px-2.5 py-1 rounded-lg bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold\">Fire UV Photon ⚡</button>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim12_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Photolysis Step 1</div>\n                        <div id=\"sim12_val_step1\" class=\"text-cyan-400 font-bold text-sm\">O₂ + UV -> O + O</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Synthesis Step 2</div>\n                        <div id=\"sim12_val_step2\" class=\"text-emerald-400 font-bold text-sm\">O + O₂ -> O₃ (Ozone)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ozone Layer Thickness</div>\n                        <div id=\"sim12_val_dobson\" class=\"text-teal-400 font-bold text-sm\">310 Dobson Units</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">UV-B Shielding Capacity</div>\n                        <div id=\"sim12_val_shield\" class=\"text-amber-400 font-bold text-sm\">98.5% Absorbed</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "13": {
    "title": "CFC Catalytic Ozone Depletion & Montreal Protocol",
    "description": "Witness chlorine radical catalytic cycles destroying stratospheric ozone, and test the 1987 Montreal Protocol treaty timeline to track Antarctic ozone recovery.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Simulation Year:</span>\n                        <input type=\"range\" id=\"sim13_year_slider\" min=\"1980\" max=\"2060\" value=\"1987\" step=\"1\" oninput=\"sim13Update()\" class=\"w-32 accent-rose-500\">\n                        <span id=\"sim13_year_txt\" class=\"text-rose-400 font-mono font-bold\">1987</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim13_btn_protocol\" onclick=\"sim13ToggleMontreal()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold\">Montreal Protocol: ACTIVE 📜</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim13_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">CFC Global Concentration</div>\n                        <div id=\"sim13_val_cfc\" class=\"text-rose-400 font-bold text-sm\">Peak 550 ppt</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Catalytic Cl Destruction</div>\n                        <div id=\"sim13_val_cl\" class=\"text-amber-400 font-bold text-sm\">Cl + O₃ -> ClO + O₂</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Antarctic Ozone Hole Area</div>\n                        <div id=\"sim13_val_hole\" class=\"text-cyan-400 font-bold text-sm\">24.5 Million km²</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Stratospheric Healing Trend</div>\n                        <div id=\"sim13_val_status\" class=\"text-emerald-400 font-bold text-sm\">Frozen at 1986 Level</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "14": {
    "title": "Substrate Enzyme Specificity Lock & Key Lab",
    "description": "Investigate Activities 13.5 and 13.6 by testing bacterial enzyme action on natural cellulose polymers (rapid decomposition) versus synthetic polyethylene plastics (0% fit, persistent for centuries).",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Test Material:</span>\n                        <select id=\"sim14_sel_material\" onchange=\"sim14Update()\" class=\"bg-slate-800 text-emerald-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"cellulose\">Cellulose (Paper / Cotton / Leaf)</option>\n                            <option value=\"protein\">Keratin / Protein (Leather / Wool)</option>\n                            <option value=\"plastic\">Polyethylene Plastic Carry Bag</option>\n                            <option value=\"glass\">Silica Glass Bottle</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim14BurySample()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Soil Burial Test (60 Days) 🪱</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim14_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Polymer Bond Type</div>\n                        <div id=\"sim14_val_bond\" class=\"text-emerald-400 font-bold text-sm\">β-1,4 Glycosidic Link</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Bacterial Enzyme Fit</div>\n                        <div id=\"sim14_val_fit\" class=\"text-teal-400 font-bold text-sm\">Perfect Lock-and-Key</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Decomposition Half-Life</div>\n                        <div id=\"sim14_val_halflife\" class=\"text-cyan-400 font-bold text-sm\">3 to 6 Weeks</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Classification</div>\n                        <div id=\"sim14_val_class\" class=\"text-emerald-400 font-bold text-sm\">100% Biodegradable</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "15": {
    "title": "Municipal Source Segregation & 5 R Studio",
    "description": "Engage with Activities 13.7 and 13.8 by sorting urban refuse into Green (Wet/Compost) and Blue (Dry/Recycle) bins to maximize compost fertilizer and prevent toxic landfill leachate.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current Waste Item:</span>\n                        <span id=\"sim15_item_name\" class=\"text-amber-400 font-bold font-mono\">Banana Peel (Kitchen Waste)</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim15SortItem('green')\" class=\"px-3 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold\">🟢 Green Bin (Wet/Compost)</button>\n                        <button onclick=\"sim15SortItem('blue')\" class=\"px-3 py-1 rounded-lg bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold\">🔵 Blue Bin (Dry/Recycle)</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim15_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Sorting Accuracy</div>\n                        <div id=\"sim15_val_accuracy\" class=\"text-emerald-400 font-bold text-sm\">100% (5/5 Sorted)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Vermicompost Produced</div>\n                        <div id=\"sim15_val_compost\" class=\"text-teal-400 font-bold text-sm\">4.5 kg Organic Fertilizer</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Landfill Diversion Rate</div>\n                        <div id=\"sim15_val_diversion\" class=\"text-cyan-400 font-bold text-sm\">88% Diverted</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Aquifer Leachate Risk</div>\n                        <div id=\"sim15_val_risk\" class=\"text-emerald-400 font-bold text-sm\">Zero Contamination</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "16": {
    "title": "Railway Beverage Container Lifecycle Studio",
    "description": "Evaluate the environmental tradeoffs in passenger train beverage containers: Reusable Glass vs Disposable Plastic vs Clay Kulhad vs Modern Paper Cup across hygiene, topsoil loss, and biodegradability.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Select Container Era:</span>\n                        <select id=\"sim16_sel_cup\" onchange=\"sim16Update()\" class=\"bg-slate-800 text-amber-400 rounded px-2 py-1 border border-slate-700\">\n                            <option value=\"glass\">1. Reusable Glass Tumblers (Early Era)</option>\n                            <option value=\"plastic\">2. Disposable Plastic/Styrofoam Cups</option>\n                            <option value=\"kulhad\">3. Terracotta Clay Kulhads</option>\n                            <option value=\"paper\">4. Food-Grade Biodegradable Paper Cups</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Daily Demand:</span>\n                        <input type=\"range\" id=\"sim16_demand_slider\" min=\"1\" max=\"10\" value=\"5\" step=\"1\" oninput=\"sim16Update()\" class=\"w-24 accent-emerald-500\">\n                        <span id=\"sim16_demand_txt\" class=\"text-emerald-400 font-mono font-bold\">5 Million/day</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim16_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Sanitary Hygiene Rating</div>\n                        <div id=\"sim16_val_hygiene\" class=\"text-rose-400 font-bold text-sm\">Poor (Washing Risk)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Fertile Topsoil Loss</div>\n                        <div id=\"sim16_val_topsoil\" class=\"text-emerald-400 font-bold text-sm\">0 Tons Mined</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Decomposition Time</div>\n                        <div id=\"sim16_val_decomp\" class=\"text-amber-400 font-bold text-sm\">1 Million Years (Glass)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Lifecycle Sustainability</div>\n                        <div id=\"sim16_val_sustain\" class=\"text-cyan-400 font-bold text-sm\">Moderate (Washing Water)</div>\n                    </div>\n                </div>\n            </div>\n        "
  }
}
